/** Internal, per-camera output scope. No engine imports or global pipeline macro mutations. */
const cameras = new WeakSet<object>();
let linearHDR = false;
export function registerAirHDRCamera(camera: object, enabled: boolean): void {
    if (enabled) cameras.add(camera);
    else cameras.delete(camera);
}
export function beginAirCameraOutput(camera: object): boolean {
    const previous = linearHDR;
    linearHDR = cameras.has(camera);
    return previous;
}
export function restoreAirCameraOutput(previous: boolean): void {
    linearHDR = previous;
}
export function isAirLinearHDRRendering(): boolean {
    return linearHDR;
}
